window.addTransactionRecord = (type, amount, source) => {
  try {
    const records = JSON.parse(
      localStorage.getItem("wallet_transactions") || "[]",
    );
    const newRecord = {
      id: Date.now(),
      type,
      // 'income' (充值/收入) 或 'expense' (支出)
      amount,
      source,
      timestamp: /* @__PURE__ */ new Date().toLocaleString(),
    };
    records.unshift(newRecord);
    localStorage.setItem("wallet_transactions", JSON.stringify(records));
    window.dispatchEvent(new Event("walletTransactionsUpdated"));
  } catch (e) {
    console.error("\u8BB0\u5F55\u4EA4\u6613\u5931\u8D25", e);
  }
};
