      const data = await response.json();
      if (parseInt(data.totalHits) > 0) {
        return data.hits.map((hit) => ({
          id: hit.id,
          url: hit.webformatURL,
          pageURL: hit.pageURL,
          tags: hit.tags,
        }));
      } else {
        console.log("Pixabay\u672A\u627E\u5230\u76F8\u5173\u56FE\u7247");
        return [];
      }
